def parse_brackets(bracket_string: str) -> List[str]:
    """ Parse the bracket string and returns each element as a string.

    >>> parse_brackets('(()()())')
    ['()', '()', '()']
    """
    open_stack = []
    result = []
    i = 0
    while i < len(bracket_string):
        if bracket_string[i] == '(':
            open_stack.append(bracket_string[i])
        else:
            if not open_stack:
                open_stack.append(bracket_string[i])
            else:
                if bracket_string[i] == ')':
                    open_stack.pop()
                elif bracket_string[i] == '[':
                    result.append('\n')
                    result.append(bracket_string[i])
                else:
                    bracket_string[i] = ' ' + bracket_string[i]

